-- Guards: Platform Admin mandate 5 Nov 2026 17:31, Course Catalogue columns: production-representative schema for the isolated fixture.
-- Every table the change reads or writes, as production has it (read read-only from fxcwkweaxjtknorudmwp, 5 Nov 2026 19:27 AEDT):
-- columns and types, not-null, defaults, primary, unique and check constraints, every foreign key (targets outside this set are created
-- as key-only tables so the constraint itself is real), indexes, RLS (on for every table; no policies; no grants to anon or authenticated)
-- and every trigger by name. Trigger functions outside this change are no-op stand-ins (the change writes none of these tables).
-- parity.sql fingerprints the result; run.sh compares it with production-parity.txt table by table.
\set ON_ERROR_STOP on
do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'anon') then create role anon nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'service_role') then create role service_role nologin bypassrls; end if;
end $$;
create schema auth; create schema extensions; create schema ref; create schema catalogue; create schema scholarship; create schema search;
create schema security; create schema pipeline; create schema pim; create schema api;
grant usage on schema public, auth, security, pipeline, catalogue, ref, search, scholarship to authenticated, anon;
create function extensions.gen_random_uuid() returns uuid language sql volatile as 'select pg_catalog.gen_random_uuid()';
-- Supabase auth: the JWT subject, as PostgREST sets it
create table auth.users (id uuid primary key, email text);
create function auth.uid() returns uuid language sql stable as $f$ select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid $f$;
grant execute on function auth.uid() to authenticated, anon;

-- key-only stand-ins for foreign-key targets outside the change
create table ref.currencies (code character(3) primary key);
create table ref.regions (id uuid primary key);
create table pim.entity_registry (id uuid primary key);
create table ref.provider_types (id uuid primary key);
create table pipeline.evidence_artifacts (id uuid primary key);
create table pipeline.sources (id uuid primary key);
create table ref.english_tests (id uuid primary key);
create table ref.course_link_types (code text primary key);
create table catalogue.course_collections (id uuid primary key);
create table scholarship.offering_cycles (id uuid primary key);
create table scholarship.scholarships (id uuid primary key);
create table pipeline.admin_jobs (id uuid primary key);
create table pipeline.course_fact_source_records (id uuid primary key);
create table pipeline.layer4_decisions (id uuid primary key);
create table pipeline.layer4_intervention_classes (code text primary key);

-- trigger functions and the title key: stand-ins with production's names and signatures
create function security.course_title_key(text) returns text language sql immutable as $f$ select lower(btrim($1)) $f$;
do $$ declare f text; begin
  foreach f in array array['catalogue.enforce_course_identifier_provider','security.sync_evidence_entity_links','security.sync_evidence_lineage_stats',
    'security.course_link_reactivation_guard_trg_v1','security.no_page_reopen_link_trg_v1','security.coverage_page_refused_host_guard','security.provider_site_followups_tg',
    'security.ai_spend_capture_v1','security.course_fee_one_current_trg','catalogue.mirror_course_registration_identifier','security.manual_fact_guard','security.manual_field_guard',
    'security.manual_column_guard','security.provider_publish_by_default','security.provider_onboarding_new_tg','security.course_intake_same_month_guard',
    'security.enrichment_flags_sync_v1','security.enrichment_flags_log_v1','security.field_enrich_items_gate_v1','security.field_enrich_items_flag_v1',
    'security.course_fee_identity_gate_tg','security.field_enrich_items_absence_trg_v1','security.ops_guard_settings_v1','security.fee_admitted_recheck_settle_tg',
    'security.cricos_identity_guard_trg_v1','security.enrichment_flags_first_v1','security.intake_failure_class_trg_v1'] loop
    execute format('create function %s() returns trigger language plpgsql as $t$ begin if tg_op = ''DELETE'' then return old; end if; return new; end $t$', f);
  end loop;
end $$;
create function security.ops_remedy_guard_active_v1() returns boolean language sql stable as 'select false';

create sequence pipeline.field_enrich_items_id_seq; create sequence pipeline.adapter_overwrite_changes_id_seq; create sequence pipeline.course_intake_date_events_id_seq;
create sequence pipeline.uni_adapter_results_id_seq; create sequence pipeline.enrichment_flags_id_seq; create sequence pipeline.layer4_interventions_id_seq;

