create table scholarship.scopes (id uuid default extensions.gen_random_uuid() not null, scholarship_id uuid not null, scope_type text not null, provider_id uuid, course_id uuid, course_collection_id uuid, study_level_id uuid, field_id uuid, country_id uuid, campus_id uuid, include_exclude text default 'include'::text not null, source_id uuid, evidence_id uuid, created_at timestamp with time zone default now() not null, cycle_id uuid);
