alter table scholarship.scopes add constraint scopes_target_shape_check CHECK ((((scope_type = 'global'::text) AND (provider_id IS NULL) AND (course_id IS NULL) AND (course_collection_id IS NULL) AND (study_level_id IS NULL) AND (field_id IS NULL) AND (country_id IS NULL) AND (campus_id IS NULL)) OR ((scope_type = 'provider'::text) AND (provider_id IS NOT NULL) AND (course_id IS NULL) AND (course_collection_id IS NULL) AND (study_level_id IS NULL) AND (field_id IS NULL) AND (country_id IS NULL) AND (campus_id IS NULL)) OR ((scope_type = 'course'::text) AND (provider_id IS NULL) AND (course_id IS NOT NULL) AND (course_collection_id IS NULL) AND (study_level_id IS NULL) AND (field_id IS NULL) AND (country_id IS NULL) AND (campus_id IS NULL)) OR ((scope_type = 'course_collection'::text) AND (provider_id IS NULL) AND (course_id IS NULL) AND (course_collection_id IS NOT NULL) AND (study_level_id IS NULL) AND (field_id IS NULL) AND (country_id IS NULL) AND (campus_id IS NULL)) OR ((scope_type = 'study_level'::text) AND (provider_id IS NULL) AND (course_id IS NULL) AND (course_collection_id IS NULL) AND (study_level_id IS NOT NULL) AND (field_id IS NULL) AND (country_id IS NULL) AND (campus_id IS NULL)) OR ((scope_type = 'field_of_study'::text) AND (provider_id IS NULL) AND (course_id IS NULL) AND (course_collection_id IS NULL) AND (study_level_id IS NULL) AND (field_id IS NOT NULL) AND (country_id IS NULL) AND (campus_id IS NULL)) OR ((scope_type = 'country'::text) AND (provider_id IS NULL) AND (course_id IS NULL) AND (course_collection_id IS NULL) AND (study_level_id IS NULL) AND (field_id IS NULL) AND (country_id IS NOT NULL) AND (campus_id IS NULL)) OR ((scope_type = 'campus'::text) AND (provider_id IS NULL) AND (course_id IS NULL) AND (course_collection_id IS NULL) AND (study_level_id IS NULL) AND (field_id IS NULL) AND (country_id IS NULL) AND (campus_id IS NOT NULL))));
alter table scholarship.scopes add constraint scopes_scope_type_check CHECK ((scope_type = ANY (ARRAY['provider'::text, 'course'::text, 'course_collection'::text, 'study_level'::text, 'field_of_study'::text, 'country'::text, 'campus'::text, 'global'::text])));
alter table scholarship.scopes add constraint scopes_pkey PRIMARY KEY (id);
CREATE INDEX scholarship_scopes_collection_idx ON scholarship.scopes USING btree (course_collection_id) WHERE (course_collection_id IS NOT NULL);
