-- RLS: on for every table except catalogue.course_identifiers and pipeline.field_absence_classes, as in production
do $$ declare r text; begin
  foreach r in array string_to_array('ref.countries,ref.subdivisions,ref.study_levels,ref.fields_of_study,ref.course_code_schemes,ref.institution_collections,catalogue.providers,catalogue.campuses,catalogue.courses,catalogue.course_campuses,catalogue.course_fees,catalogue.course_intakes,catalogue.course_english_requirements,catalogue.course_registrations,catalogue.course_academic_options,catalogue.course_links,catalogue.provider_collection_memberships,scholarship.scopes,search.course_documents,security.roles,security.user_roles,pipeline.platform_toolsets,pipeline.platform_toolset_settings,pipeline.component_register,pipeline.field_enrich_items,pipeline.enrich_value_retractions,pipeline.adapter_overwrite_changes,pipeline.layer2_field_admissions,pipeline.layer4_admission_checks,pipeline.course_intake_date_events,pipeline.manual_edit_log,pipeline.uni_adapters,pipeline.uni_adapter_results,pipeline.coverage_course_pages,pipeline.course_attribute_coverage,pipeline.enrichment_flags,pipeline.layer4_interventions', ',') loop
    execute format('alter table %s enable row level security', r);
  end loop;
end $$;

